import type { DependencyItem } from "../types/licence";

/**
 * Parses the HTML generated by `cargo about generate about.hbs` into a clean,
 * structured array of DependencyItem records sorted alphabetically by crate name.
 *
 * @param html The raw or sanitized HTML string.
 * @returns An array of DependencyItem records.
 */
export function parseRustLicencesHtml(html: string): DependencyItem[] {
  if (!html || typeof html !== "string" || html.trim().length === 0) {
    return [];
  }

  // Use DOMParser if available (browser & Vitest jsdom/happy-dom)
  if (typeof DOMParser !== "undefined") {
    try {
      const parser = new DOMParser();
      const doc = parser.parseFromString(html, "text/html");
      const cards = doc.querySelectorAll(".license-card");
      const items: DependencyItem[] = [];

      cards.forEach((card) => {
        const licenceName = card.querySelector(".license-name")?.textContent?.trim() || "Unknown";
        const text = card.querySelector(".license-text pre")?.textContent?.trim() || "";
        const listItems = card.querySelectorAll(".license-crates li");

        listItems.forEach((li) => {
          const strong = li.querySelector("strong");
          const name = strong?.textContent?.trim() || "";
          if (!name) return;

          const rawText = li.textContent || "";
          const verMatch = rawText.match(/\(v([^)]+)\)/);
          const version = verMatch ? verMatch[1].trim() : "";

          const link = li.querySelector("a");
          const repository = link?.getAttribute("href")?.trim() || "";

          items.push({
            name,
            version,
            licence: licenceName,
            repository,
            text,
          });
        });
      });

      return items.sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));
    } catch {
      // Fall through to regex-based parser
    }
  }

  return parseRustLicencesHtmlRegex(html);
}

/**
 * Regex-based fallback parser for non-browser/non-DOM environments.
 */
export function parseRustLicencesHtmlRegex(html: string): DependencyItem[] {
  const items: DependencyItem[] = [];
  const cardRegex =
    /<details[^>]*class=["'][^"']*license-card[^"']*["'][^>]*>([\s\S]*?)<\/details>/gi;
  let cardMatch: RegExpExecArray | null;

  while ((cardMatch = cardRegex.exec(html)) !== null) {
    const cardContent = cardMatch[1];
    const nameMatch = cardContent.match(
      /<span[^>]*class=["'][^"']*license-name[^"']*["'][^>]*>([\s\S]*?)<\/span>/i
    );
    const licenceName = nameMatch ? nameMatch[1].replace(/<[^>]+>/g, "").trim() : "Unknown";

    const textMatch = cardContent.match(/<pre[^>]*>([\s\S]*?)<\/pre>/i);
    const text = textMatch
      ? textMatch[1]
          .replace(/&quot;/g, '"')
          .replace(/&amp;/g, "&")
          .replace(/&lt;/g, "<")
          .replace(/&gt;/g, ">")
          .trim()
      : "";

    const liRegex = /<li[^>]*>([\s\S]*?)<\/li>/gi;
    let liMatch: RegExpExecArray | null;

    while ((liMatch = liRegex.exec(cardContent)) !== null) {
      const liContent = liMatch[1];
      const strongMatch = liContent.match(/<strong[^>]*>([\s\S]*?)<\/strong>/i);
      const name = strongMatch ? strongMatch[1].replace(/<[^>]+>/g, "").trim() : "";
      if (!name) continue;

      const verMatch = liContent.match(/\(v([^)]+)\)/i);
      const version = verMatch ? verMatch[1].trim() : "";

      const hrefMatch = liContent.match(/href=["']([^"']+)["']/i);
      const repository = hrefMatch ? hrefMatch[1].trim() : "";

      items.push({
        name,
        version,
        licence: licenceName,
        repository,
        text,
      });
    }
  }

  return items.sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));
}
